CREATE TABLE finance_category (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,parent_id UUID,name VARCHAR(256) NOT NULL,kind VARCHAR(24) NOT NULL DEFAULT 'EXPENSE',archived BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(parent_id) REFERENCES finance_category(id),UNIQUE(ledger_id,name)); CREATE TABLE finance_tag (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,name VARCHAR(128) NOT NULL,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),UNIQUE(ledger_id,name)); ALTER TABLE finance_transaction ADD CONSTRAINT fk_finance_transaction_category FOREIGN KEY(category_id) REFERENCES finance_category(id);
